import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    n = int(data.split()[0])
    if n <= 0:
        return
    result = []
    for i in range(n, 0, -1):
        result.append(chr(ord('A') + i - 1) * i)
    sys.stdout.write("\n".join(result) + "\n")

if __name__ == "__main__":
    main()
